// ---- Logging ----

/** Never a silent default: every unparseable (non-null) CSS value logs
 *  here before the caller substitutes the fallback. */
private fun warn(message: String) {
    Log.w("AlmadarTheme", message)
}

// ---- Deterministic CSS-value parsers ----

private fun isUnresolvedVarRef(raw: String): Boolean = raw.startsWith("var(")

private fun numericComponents(raw: String): List<Double>? {
    val open = raw.indexOf('(')
    val close = raw.lastIndexOf(')')
    if (open < 0 || close < 0 || close <= open) return null
    val inner = raw.substring(open + 1, close)
    return inner.split(",").map { it.trim() }.map {
        val cleaned = if (it.endsWith("%")) it.dropLast(1) else it
        cleaned.toDoubleOrNull() ?: return null
    }
}

private fun parseHexColor(raw: String): Color? {
    var hex = raw.removePrefix("#")
    if (!hex.all { it.isDigit() || it.lowercaseChar() in 'a'..'f' }) return null
    if (hex.length == 3) hex = hex.map { "$it$it" }.joinToString("")
    return try {
        when (hex.length) {
            6 -> {
                val v = hex.toLong(16)
                Color((v shr 16 and 0xFF).toInt(), (v shr 8 and 0xFF).toInt(), (v and 0xFF).toInt())
            }
            8 -> {
                val v = hex.toLong(16)
                Color((v shr 24 and 0xFF).toInt(), (v shr 16 and 0xFF).toInt(), (v shr 8 and 0xFF).toInt(), (v and 0xFF).toInt())
            }
            else -> null
        }
    } catch (e: NumberFormatException) { null }
}

private fun parseRgbColor(raw: String): Color? {
    val c = numericComponents(raw) ?: return null
    if (c.size < 3) return null
    val a = if (c.size >= 4) c[3] else 1.0
    return Color((c[0] / 255).toFloat(), (c[1] / 255).toFloat(), (c[2] / 255).toFloat(), a.toFloat())
}

private fun parseHslColor(raw: String): Color? {
    val c = numericComponents(raw) ?: return null
    if (c.size < 3) return null
    val a = if (c.size >= 4) c[3] else 1.0
    val h = c[0].toFloat(); val s = (c[1] / 100).toFloat(); val l = (c[2] / 100).toFloat()
    val hsl = floatArrayOf(h, s, l)
    return Color(androidx.core.graphics.ColorUtils.HSLToColor(hsl)).copy(alpha = a.toFloat())
}

fun parseCssColor(raw: String?, fallback: Color): Color {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("color: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw == "transparent") return Color.Transparent
    if (raw.startsWith("#")) parseHexColor(raw)?.let { return it }
    if (raw.startsWith("rgb")) parseRgbColor(raw)?.let { return it }
    if (raw.startsWith("hsl")) parseHslColor(raw)?.let { return it }
    warn("color: unparseable value \"$raw\"")
    return fallback
}

fun parseCssLength(raw: String?, fallback: Dp): Dp {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("length: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw.endsWith("px")) return raw.dropLast(2).toDoubleOrNull()?.dp ?: fallback.also { warn("length: unparseable value \"$raw\"") }
    if (raw.endsWith("rem")) return raw.dropLast(3).toDoubleOrNull()?.let { (it * 16).dp } ?: fallback.also { warn("length: unparseable value \"$raw\"") }
    raw.toDoubleOrNull()?.let { return it.dp }
    warn("length: unparseable value \"$raw\"")
    return fallback
}

fun parseCssNumber(raw: String?, fallback: Double): Double {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("number: unresolved CSS var reference \"$raw\""); return fallback }
    raw.toDoubleOrNull()?.let { return it }
    warn("number: unparseable value \"$raw\"")
    return fallback
}

/** Milliseconds, matching Compose `AnimationSpec` durations (Int). */
fun parseCssDurationMs(raw: String?, fallback: Int): Int {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("duration: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw.endsWith("ms")) return raw.dropLast(2).toDoubleOrNull()?.toInt() ?: fallback.also { warn("duration: unparseable value \"$raw\"") }
    if (raw.endsWith("s")) return raw.dropLast(1).toDoubleOrNull()?.let { (it * 1000).toInt() } ?: fallback.also { warn("duration: unparseable value \"$raw\"") }
    raw.toDoubleOrNull()?.let { return it.toInt() }
    warn("duration: unparseable value \"$raw\"")
    return fallback
}

data class CssCurve(val x1: Float, val y1: Float, val x2: Float, val y2: Float) {
    fun toEasing(): Easing = CubicBezierEasing(x1, y1, x2, y2)
}

fun parseCssEasing(raw: String?, fallback: CssCurve): CssCurve {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("easing: unresolved CSS var reference \"$raw\""); return fallback }
    when (raw) {
        "linear" -> return CssCurve(0f, 0f, 1f, 1f)
        "ease" -> return CssCurve(0.25f, 0.1f, 0.25f, 1f)
        "ease-in" -> return CssCurve(0.42f, 0f, 1f, 1f)
        "ease-out" -> return CssCurve(0f, 0f, 0.58f, 1f)
        "ease-in-out" -> return CssCurve(0.42f, 0f, 0.58f, 1f)
    }
    if (raw.startsWith("cubic-bezier(")) {
        val c = numericComponents(raw)
        if (c != null && c.size == 4) return CssCurve(c[0].toFloat(), c[1].toFloat(), c[2].toFloat(), c[3].toFloat())
    }
    warn("easing: unparseable value \"$raw\"")
    return fallback
}

