data class CssBackdrop(val blurRadius: Dp, val saturation: Double)

/** A CSS image layer list kept as its declared string: gradients, tiles and SVG
 *  data-URI masks have no native value to parse into, so a renderer interprets the CSS. */
sealed class CssSurfaceImage {
    object None : CssSurfaceImage()
    data class Css(val value: String) : CssSurfaceImage()
}

/** One layer of a CSS background-size / mask-size list; null = auto. */
data class CssTileSize(val width: Dp?, val height: Dp?)

/** clamp(lower, fixed + preferredVw vw, upper); a plain length has lower == fixed == upper. */
data class CssResponsiveLength(val lower: Dp, val preferredVw: Double, val fixed: Dp, val upper: Dp) {
    fun resolve(viewportWidth: Dp): Dp {
        val preferred = fixed.value + (preferredVw / 100.0).toFloat() * viewportWidth.value
        return Dp(minOf(maxOf(preferred, lower.value), upper.value))
    }
}

data class AlmadarHeadingVoice(
    val weight: FontWeight,
    val transform: CssTextTransform,
    val tracking: CssTracking,
    val style: CssFontSlant,
    val shadow: CssShadow?,
)

private fun splitTopLevel(raw: String, separator: Char): List<String> {
    val parts = mutableListOf<String>()
    var depth = 0
    val current = StringBuilder()
    for (ch in raw) {
        if (ch == '(') depth++ else if (ch == ')') depth--
        if (ch == separator && depth == 0) {
            parts.add(current.toString())
            current.setLength(0)
        } else {
            current.append(ch)
        }
    }
    parts.add(current.toString())
    return parts.map { it.trim() }.filter { it.isNotEmpty() }
}

private fun lengthValue(t: String): Dp? {
    if (t.endsWith("px")) return t.dropLast(2).toDoubleOrNull()?.dp
    if (t.endsWith("rem")) return t.dropLast(3).toDoubleOrNull()?.let { (it * 16).dp }
    return t.toDoubleOrNull()?.dp
}

private fun strictColor(t: String): Color? = when {
    t == "transparent" -> Color.Transparent
    t.startsWith("#") -> parseHexColor(t)
    t.startsWith("rgb") -> parseRgbColor(t)
    t.startsWith("hsl") -> parseHslColor(t)
    else -> null
}

private fun shadowLayer(raw: String, defaultColor: Color): CssShadow? {
    val lengths = mutableListOf<Dp>()
    var layerColor: Color? = null
    var inset = false
    for (t in splitTopLevel(raw, ' ')) {
        if (t == "inset") { inset = true; continue }
        val len = lengthValue(t)
        if (len != null) { lengths.add(len); continue }
        val c = strictColor(t)
        if (c != null) { layerColor = c; continue }
        return null
    }
    if (lengths.size < 2 || lengths.size > 4) return null
    return CssShadow(
        color = layerColor ?: defaultColor,
        radius = if (lengths.size >= 3) lengths[2] else 0.dp,
        x = lengths[0],
        y = lengths[1],
        spread = if (lengths.size == 4) lengths[3] else 0.dp,
        inset = inset,
    )
}

private fun shadowLayers(raw: String, defaultColor: Color): CssShadow? {
    val layers = splitTopLevel(raw, ',').map { shadowLayer(it, defaultColor) }
    if (layers.isEmpty() || layers.any { it == null }) return null
    val ok = layers.filterNotNull()
    return ok.first().copy(underlays = ok.drop(1))
}

/** var(--shadow-<key>) resolves against the theme's own legacy shadows map (the same
 *  table the web cascade reads); any other value passes through unchanged. */
fun resolveShadowRef(raw: String?, shadows: Map<String, String>?): String? {
    if (raw == null || !raw.startsWith("var(--shadow-") || !raw.endsWith(")")) return raw
    val key = raw.removePrefix("var(--shadow-").removeSuffix(")")
    return shadows?.get(key) ?: raw
}

/** var(--radius-<key>) resolves against the theme's own legacy radii map (the same
 *  table the web cascade reads); any other value passes through unchanged. */
fun resolveRadiusRef(raw: String?, radii: Map<String, String>?): String? {
    if (raw == null || !raw.startsWith("var(--radius-") || !raw.endsWith(")")) return raw
    val key = raw.removePrefix("var(--radius-").removeSuffix(")")
    return radii?.get(key) ?: raw
}

fun parseCssShadow(raw: String?, fallback: CssShadow): CssShadow {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("shadow: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw == "none") return CssShadow(Color.Transparent, 0.dp, 0.dp, 0.dp)
    shadowLayers(raw, fallback.color)?.let { return it }
    warn("shadow: unparseable value \"$raw\"")
    return fallback
}

/** CSS text-shadow: none is null; layers beyond the first ride underlays. */
fun parseCssTextShadow(raw: String?, fallback: CssShadow?): CssShadow? {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("textShadow: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw == "none") return null
    shadowLayers(raw, Color.Black)?.let { return it }
    warn("textShadow: unparseable value \"$raw\"")
    return fallback
}

fun parseCssCornerShape(raw: String?, fallback: CssCornerShape): CssCornerShape {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("cornerShape: unresolved CSS var reference \"$raw\""); return fallback }
    when (raw) {
        "round" -> return CssCornerShape.Round
        "squircle" -> return CssCornerShape.Squircle
        "bevel" -> return CssCornerShape.Bevel
        "scoop" -> return CssCornerShape.Scoop
        "notch" -> return CssCornerShape.Notch
    }
    if (raw.startsWith("superellipse(")) {
        val c = numericComponents(raw)
        if (c != null && c.size == 1) return CssCornerShape.Superellipse(c[0])
    }
    warn("cornerShape: unparseable value \"$raw\"")
    return fallback
}

fun parseCssBorderStyle(raw: String?, fallback: CssBorderStyle): CssBorderStyle {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("borderStyle: unresolved CSS var reference \"$raw\""); return fallback }
    CssBorderStyle.values().firstOrNull { it.cssName == raw }?.let { return it }
    warn("borderStyle: unparseable value \"$raw\"")
    return fallback
}

fun parseCssTextTransform(raw: String?, fallback: CssTextTransform): CssTextTransform {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("textTransform: unresolved CSS var reference \"$raw\""); return fallback }
    CssTextTransform.values().firstOrNull { it.cssName == raw }?.let { return it }
    warn("textTransform: unparseable value \"$raw\"")
    return fallback
}

fun parseCssFontSlant(raw: String?, fallback: CssFontSlant): CssFontSlant {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("fontSlant: unresolved CSS var reference \"$raw\""); return fallback }
    CssFontSlant.values().firstOrNull { it.cssName == raw }?.let { return it }
    warn("fontSlant: unparseable value \"$raw\"")
    return fallback
}

/** CSS font-weight: normal, bold or a number in 1..1000. */
fun parseCssFontWeight(raw: String?, fallback: FontWeight): FontWeight {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("fontWeight: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw == "normal") return FontWeight.Normal
    if (raw == "bold") return FontWeight.Bold
    val n = raw.toDoubleOrNull()
    if (n != null && n >= 1.0 && n <= 1000.0) return FontWeight(n.toInt())
    warn("fontWeight: unparseable value \"$raw\"")
    return fallback
}

fun parseCssTracking(raw: String?, fallback: CssTracking): CssTracking {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("tracking: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw == "normal") return CssTracking(0.0, true)
    if (raw.endsWith("rem")) raw.dropLast(3).toDoubleOrNull()?.let { return CssTracking(it * 16, false) }
    if (raw.endsWith("em")) raw.dropLast(2).toDoubleOrNull()?.let { return CssTracking(it, true) }
    if (raw.endsWith("px")) raw.dropLast(2).toDoubleOrNull()?.let { return CssTracking(it, false) }
    if (raw.toDoubleOrNull() == 0.0) return CssTracking(0.0, true)
    warn("tracking: unparseable value \"$raw\"")
    return fallback
}

/** CSS backdrop-filter limited to blur(<length>) and saturate(<n|%>); none is null. */
fun parseCssBackdrop(raw: String?, fallback: CssBackdrop?): CssBackdrop? {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("backdrop: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw == "none") return null
    var blur = 0.dp
    var saturation = 1.0
    for (t in splitTopLevel(raw, ' ')) {
        val open = t.indexOf('(')
        if (open < 0 || !t.endsWith(")")) { warn("backdrop: unparseable value \"$raw\""); return fallback }
        val name = t.substring(0, open)
        val arg = t.substring(open + 1, t.length - 1)
        if (name == "blur") {
            val n = lengthValue(arg)
            if (n != null) { blur = n; continue }
        }
        if (name == "saturate") {
            if (arg.endsWith("%")) {
                val n = arg.dropLast(1).toDoubleOrNull()
                if (n != null) { saturation = n / 100; continue }
            } else {
                val n = arg.toDoubleOrNull()
                if (n != null) { saturation = n; continue }
            }
        }
        warn("backdrop: unsupported filter \"$t\" in \"$raw\"")
        return fallback
    }
    return CssBackdrop(blur, saturation)
}

private val cssImageFunctions = listOf("linear-gradient(", "radial-gradient(", "conic-gradient(", "repeating-linear-gradient(", "repeating-radial-gradient(", "repeating-conic-gradient(", "url(")

fun parseCssSurfaceImage(raw: String?, fallback: CssSurfaceImage): CssSurfaceImage {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("cssImage: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw == "none") return CssSurfaceImage.None
    if (cssImageFunctions.any { raw.startsWith(it) }) return CssSurfaceImage.Css(raw)
    warn("cssImage: unparseable value \"$raw\"")
    return fallback
}

fun parseCssTileSizes(raw: String?, fallback: List<CssTileSize>): List<CssTileSize> {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("tileSizes: unresolved CSS var reference \"$raw\""); return fallback }
    val out = mutableListOf<CssTileSize>()
    for (layer in splitTopLevel(raw, ',')) {
        val parts = splitTopLevel(layer, ' ')
        if (parts.size != 1 && parts.size != 2) { warn("tileSizes: unparseable value \"$raw\""); return fallback }
        val dims = mutableListOf<Dp?>()
        for (p in parts) {
            if (p == "auto") { dims.add(null); continue }
            val n = lengthValue(p)
            if (n == null) { warn("tileSizes: unparseable value \"$raw\""); return fallback }
            dims.add(n)
        }
        out.add(CssTileSize(dims[0], if (dims.size == 2) dims[1] else null))
    }
    return out
}

fun parseCssResponsiveLength(raw: String?, fallback: CssResponsiveLength): CssResponsiveLength {
    if (raw.isNullOrEmpty()) return fallback
    if (isUnresolvedVarRef(raw)) { warn("responsiveLength: unresolved CSS var reference \"$raw\""); return fallback }
    if (raw.startsWith("clamp(") && raw.endsWith(")")) {
        val args = splitTopLevel(raw.removePrefix("clamp(").removeSuffix(")"), ',')
        if (args.size == 3) {
            val lo = lengthValue(args[0])
            val hi = lengthValue(args[2])
            if (lo != null && hi != null) {
                if (args[1].endsWith("vw")) {
                    val vw = args[1].dropLast(2).toDoubleOrNull()
                    if (vw != null) return CssResponsiveLength(lo, vw, 0.dp, hi)
                }
                val fx = lengthValue(args[1])
                if (fx != null) return CssResponsiveLength(lo, 0.0, fx, hi)
            }
        }
    } else {
        val v = lengthValue(raw)
        if (v != null) return CssResponsiveLength(v, 0.0, v, v)
    }
    warn("responsiveLength: unparseable value \"$raw\"")
    return fallback
}

/** Null means "use the platform default font family" (Material3's own
 *  `Typography` default) — a generic sans/system keyword or an unresolved
 *  `var(...)` reference. A CSS-named font with no bundled Compose
 *  resource also resolves to null (there is no font FILE to load; this is
 *  the same behavior a browser falls back to when a named font is not
 *  installed, not a parse error, so no warning) — monospace is the one
 *  named case every shipped preset actually needs, and Compose ships it
 *  as a built-in generic family. */
fun parseCssFontFamily(raw: String?): FontFamily? {
    if (raw.isNullOrEmpty()) return null
    for (candidate in raw.split(",")) {
        val name = candidate.trim().trim('\'', '"')
        when (name.lowercase()) {
            "sans-serif", "ui-sans-serif" -> return FontFamily.SansSerif
            "serif", "ui-serif" -> return FontFamily.Serif
            "monospace", "ui-monospace" -> return FontFamily.Monospace
            "cursive" -> return FontFamily.Cursive
        }
    }
    return null
}

