object AlmadarTheme {
    /** `minimalist` preset's base (light) tokens, baked at generation time —
     *  always available before the kernel snapshot supplies a live theme
     *  (set by the kernel snapshot (wave B7)). */
    val fallback: AlmadarThemeValue by lazy { resolve(ThemeTokensJson.fallback, ColorMode.Light, null) }

    /** `tokens` is assumed already resolved for `mode` (dark-variant merge
     *  happens upstream, `orbital-core::runtime::theme::resolve` — wave
     *  C1(c)); `mode` is carried for callers that need it, not used to
     *  re-merge here. `fallbackChain` supplies the "unparseable" fallback
     *  for every leaf — pass null only when bootstrapping `fallback` itself. */
    fun resolve(tokens: ThemeTokensJson, mode: ColorMode, fallbackChain: AlmadarThemeValue?): AlmadarThemeValue {
        val fb = fallbackChain ?: bootstrapDefaults

        val colorAxis = tokens.color
        val legacyColors = tokens.colors ?: emptyMap()
        val color = AlmadarColorPalette(
            primary = parseCssColor(colorAxis?.primary ?: legacyColors["primary"], fb.color.primary),
            primaryHover = parseCssColor(colorAxis?.primaryHover ?: legacyColors["primary-hover"], fb.color.primaryHover),
            primaryForeground = parseCssColor(colorAxis?.primaryForeground ?: legacyColors["primary-foreground"], fb.color.primaryForeground),
            secondary = parseCssColor(colorAxis?.secondary ?: legacyColors["secondary"], fb.color.secondary),
            secondaryHover = parseCssColor(colorAxis?.secondaryHover ?: legacyColors["secondary-hover"], fb.color.secondaryHover),
            secondaryForeground = parseCssColor(colorAxis?.secondaryForeground ?: legacyColors["secondary-foreground"], fb.color.secondaryForeground),
            accent = parseCssColor(colorAxis?.accent ?: legacyColors["accent"], fb.color.accent),
            accentForeground = parseCssColor(colorAxis?.accentForeground ?: legacyColors["accent-foreground"], fb.color.accentForeground),
            muted = parseCssColor(colorAxis?.muted ?: legacyColors["muted"], fb.color.muted),
            mutedForeground = parseCssColor(colorAxis?.mutedForeground ?: legacyColors["muted-foreground"], fb.color.mutedForeground),
            background = parseCssColor(colorAxis?.background ?: legacyColors["background"], fb.color.background),
            foreground = parseCssColor(colorAxis?.foreground ?: legacyColors["foreground"], fb.color.foreground),
            card = parseCssColor(colorAxis?.card ?: legacyColors["card"], fb.color.card),
            cardForeground = parseCssColor(colorAxis?.cardForeground ?: legacyColors["card-foreground"], fb.color.cardForeground),
            surface = parseCssColor(colorAxis?.surface ?: legacyColors["surface"], fb.color.surface),
            border = parseCssColor(colorAxis?.border ?: legacyColors["border"], fb.color.border),
            input = parseCssColor(colorAxis?.input ?: legacyColors["input"], fb.color.input),
            ring = parseCssColor(colorAxis?.ring ?: legacyColors["ring"], fb.color.ring),
            error = parseCssColor(colorAxis?.error ?: legacyColors["error"], fb.color.error),
            errorForeground = parseCssColor(colorAxis?.errorForeground ?: legacyColors["error-foreground"], fb.color.errorForeground),
            success = parseCssColor(colorAxis?.success ?: legacyColors["success"], fb.color.success),
            successForeground = parseCssColor(colorAxis?.successForeground ?: legacyColors["success-foreground"], fb.color.successForeground),
            warning = parseCssColor(colorAxis?.warning ?: legacyColors["warning"], fb.color.warning),
            warningForeground = parseCssColor(colorAxis?.warningForeground ?: legacyColors["warning-foreground"], fb.color.warningForeground),
            info = parseCssColor(colorAxis?.info ?: legacyColors["info"], fb.color.info),
            infoForeground = parseCssColor(colorAxis?.infoForeground ?: legacyColors["info-foreground"], fb.color.infoForeground),
            tableHeader = parseCssColor(colorAxis?.tableHeader ?: legacyColors["table-header"], fb.color.tableHeader),
            tableBorder = parseCssColor(colorAxis?.tableBorder ?: legacyColors["table-border"], fb.color.tableBorder),
            tableRowHover = parseCssColor(colorAxis?.tableRowHover ?: legacyColors["table-row-hover"], fb.color.tableRowHover),
            surfaceHover = parseCssColor(colorAxis?.surfaceHover ?: legacyColors["surface-hover"], fb.color.surfaceHover),
            borderHover = parseCssColor(colorAxis?.borderHover ?: legacyColors["border-hover"], fb.color.borderHover),
            placeholder = parseCssColor(colorAxis?.placeholder ?: legacyColors["placeholder"], fb.color.placeholder),
            scrim = parseCssColor(colorAxis?.scrim ?: legacyColors["scrim"], fb.color.scrim),
        )

        val densityAxis = tokens.density
        val spacing = mapOf(
            "space0" to parseCssLength(densityAxis?.spacing?.space0, fb.density.spacing["space0"] ?: 4.dp),
            "space1" to parseCssLength(densityAxis?.spacing?.space1, fb.density.spacing["space1"] ?: 4.dp),
            "space2" to parseCssLength(densityAxis?.spacing?.space2, fb.density.spacing["space2"] ?: 4.dp),
            "space3" to parseCssLength(densityAxis?.spacing?.space3, fb.density.spacing["space3"] ?: 4.dp),
            "space4" to parseCssLength(densityAxis?.spacing?.space4, fb.density.spacing["space4"] ?: 4.dp),
            "space5" to parseCssLength(densityAxis?.spacing?.space5, fb.density.spacing["space5"] ?: 4.dp),
            "space6" to parseCssLength(densityAxis?.spacing?.space6, fb.density.spacing["space6"] ?: 4.dp),
            "space7" to parseCssLength(densityAxis?.spacing?.space7, fb.density.spacing["space7"] ?: 4.dp),
            "space8" to parseCssLength(densityAxis?.spacing?.space8, fb.density.spacing["space8"] ?: 4.dp),
            "space9" to parseCssLength(densityAxis?.spacing?.space9, fb.density.spacing["space9"] ?: 4.dp),
            "space10" to parseCssLength(densityAxis?.spacing?.space10, fb.density.spacing["space10"] ?: 4.dp),
            "space11" to parseCssLength(densityAxis?.spacing?.space11, fb.density.spacing["space11"] ?: 4.dp),
            "space12" to parseCssLength(densityAxis?.spacing?.space12, fb.density.spacing["space12"] ?: 4.dp),
        )
        val density = AlmadarDensityScale(
            spacing = spacing,
            buttonHeightSm = parseCssLength(densityAxis?.buttonHeightSm, fb.density.buttonHeightSm),
            buttonHeightMd = parseCssLength(densityAxis?.buttonHeightMd, fb.density.buttonHeightMd),
            buttonHeightLg = parseCssLength(densityAxis?.buttonHeightLg, fb.density.buttonHeightLg),
            inputHeightSm = parseCssLength(densityAxis?.inputHeightSm, fb.density.inputHeightSm),
            inputHeightMd = parseCssLength(densityAxis?.inputHeightMd, fb.density.inputHeightMd),
            inputHeightLg = parseCssLength(densityAxis?.inputHeightLg, fb.density.inputHeightLg),
            rowHeightCompact = parseCssLength(densityAxis?.rowHeightCompact, fb.density.rowHeightCompact),
            rowHeightNormal = parseCssLength(densityAxis?.rowHeightNormal, fb.density.rowHeightNormal),
            rowHeightSpacious = parseCssLength(densityAxis?.rowHeightSpacious, fb.density.rowHeightSpacious),
            cardPaddingSm = parseCssLength(densityAxis?.cardPaddingSm, fb.density.cardPaddingSm),
            cardPaddingMd = parseCssLength(densityAxis?.cardPaddingMd, fb.density.cardPaddingMd),
            cardPaddingLg = parseCssLength(densityAxis?.cardPaddingLg, fb.density.cardPaddingLg),
            dialogPadding = parseCssLength(densityAxis?.dialogPadding, fb.density.dialogPadding),
            sectionGap = parseCssLength(densityAxis?.sectionGap, fb.density.sectionGap),
        )

        val typeAxis = tokens.typeScale
        fun scaleEntry(e: TypeScaleEntryJson?, fb: AlmadarTypeEntry): AlmadarTypeEntry = AlmadarTypeEntry(
            size = parseCssLength(e?.size, Dp(fb.size.value)).value.sp,
            lineHeight = parseCssLength(e?.lineHeight, Dp(fb.lineHeight.value)).value.sp,
        )
        val scaleFallback = mapOf(
            "xs" to (fb.typeScale.scale["xs"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "sm" to (fb.typeScale.scale["sm"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "base" to (fb.typeScale.scale["base"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "lg" to (fb.typeScale.scale["lg"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "xl" to (fb.typeScale.scale["xl"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "2xl" to (fb.typeScale.scale["2xl"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "3xl" to (fb.typeScale.scale["3xl"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "4xl" to (fb.typeScale.scale["4xl"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "display-1" to (fb.typeScale.scale["display-1"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
            "display-2" to (fb.typeScale.scale["display-2"] ?: AlmadarTypeEntry(16.sp, 20.sp)),
        )
        val scale = mapOf(
            "xs" to scaleEntry(typeAxis?.scale?.xs, scaleFallback["xs"]!!),
            "sm" to scaleEntry(typeAxis?.scale?.sm, scaleFallback["sm"]!!),
            "base" to scaleEntry(typeAxis?.scale?.base, scaleFallback["base"]!!),
            "lg" to scaleEntry(typeAxis?.scale?.lg, scaleFallback["lg"]!!),
            "xl" to scaleEntry(typeAxis?.scale?.xl, scaleFallback["xl"]!!),
            "2xl" to scaleEntry(typeAxis?.scale?.xl2, scaleFallback["2xl"]!!),
            "3xl" to scaleEntry(typeAxis?.scale?.xl3, scaleFallback["3xl"]!!),
            "4xl" to scaleEntry(typeAxis?.scale?.xl4, scaleFallback["4xl"]!!),
            "display-1" to scaleEntry(typeAxis?.scale?.display1, scaleFallback["display-1"]!!),
            "display-2" to scaleEntry(typeAxis?.scale?.display2, scaleFallback["display-2"]!!),
        )
        val displayFamily = parseCssFontFamily(typeAxis?.displayFamily ?: typeAxis?.bodyFamily)
        val bodyFamily = parseCssFontFamily(typeAxis?.bodyFamily ?: typeAxis?.displayFamily)
        val monoFamily = parseCssFontFamily(typeAxis?.monoFamily ?: typeAxis?.bodyFamily)
        fun resolvedIntent(i: TypeIntentJson?, fallbackKey: String): AlmadarTypeIntent {
            val key = i?.size ?: fallbackKey
            val weight = when (i?.weight) {
                "bold" -> FontWeight.Bold
                "medium" -> FontWeight.Medium
                else -> FontWeight.Normal
            }
            val entry = scale[key] ?: scale["base"]!!
            val family = when (i?.slot) {
                "display" -> displayFamily
                "mono" -> monoFamily
                else -> bodyFamily
            }
            return AlmadarTypeIntent(style = TextStyle(fontSize = entry.size, lineHeight = entry.lineHeight, fontWeight = weight, fontFamily = family))
        }
        val heading = AlmadarHeadingVoice(
            weight = parseCssFontWeight(typeAxis?.headingWeight, fb.typeScale.heading.weight),
            transform = parseCssTextTransform(typeAxis?.headingTransform, fb.typeScale.heading.transform),
            tracking = parseCssTracking(typeAxis?.headingTracking, fb.typeScale.heading.tracking),
            style = parseCssFontSlant(typeAxis?.headingStyle, fb.typeScale.heading.style),
            shadow = parseCssTextShadow(typeAxis?.headingShadow, fb.typeScale.heading.shadow),
        )
        val typeScale = AlmadarTypeScale(
            displayFamily = parseCssFontFamily(typeAxis?.displayFamily),
            bodyFamily = parseCssFontFamily(typeAxis?.bodyFamily),
            monoFamily = parseCssFontFamily(typeAxis?.monoFamily),
            heading = heading,
            scale = scale,
            headingMajor = resolvedIntent(typeAxis?.intents?.headingMajor, "base"),
            headingMinor = resolvedIntent(typeAxis?.intents?.headingMinor, "base"),
            bodyEmphasis = resolvedIntent(typeAxis?.intents?.bodyEmphasis, "base"),
            bodyDefault = resolvedIntent(typeAxis?.intents?.bodyDefault, "base"),
            bodyQuiet = resolvedIntent(typeAxis?.intents?.bodyQuiet, "base"),
            caption = resolvedIntent(typeAxis?.intents?.caption, "base"),
            numeric = resolvedIntent(typeAxis?.intents?.numeric, "base"),
        )

        val motionAxis = tokens.motion
        val durationsMs = mapOf(
            "instant" to parseCssDurationMs(motionAxis?.durations?.instant, fb.motion.durationsMs["instant"] ?: 200),
            "fast" to parseCssDurationMs(motionAxis?.durations?.fast, fb.motion.durationsMs["fast"] ?: 200),
            "normal" to parseCssDurationMs(motionAxis?.durations?.normal, fb.motion.durationsMs["normal"] ?: 200),
            "slow" to parseCssDurationMs(motionAxis?.durations?.slow, fb.motion.durationsMs["slow"] ?: 200),
            "dramatic" to parseCssDurationMs(motionAxis?.durations?.dramatic, fb.motion.durationsMs["dramatic"] ?: 200),
        )
        val easings = mapOf(
            "linear" to parseCssEasing(motionAxis?.easings?.linear, fb.motion.easings["linear"] ?: CssCurve(0f, 0f, 1f, 1f)),
            "standard" to parseCssEasing(motionAxis?.easings?.standard, fb.motion.easings["standard"] ?: CssCurve(0f, 0f, 1f, 1f)),
            "emphasized" to parseCssEasing(motionAxis?.easings?.emphasized, fb.motion.easings["emphasized"] ?: CssCurve(0f, 0f, 1f, 1f)),
            "spring" to parseCssEasing(motionAxis?.easings?.spring, fb.motion.easings["spring"] ?: CssCurve(0f, 0f, 1f, 1f)),
        )
        fun resolvedMotionIntent(i: MotionIntentJson?, fb: AlmadarMotionIntent): AlmadarMotionIntent {
            val duration = durationsMs[i?.duration] ?: fb.durationMs
            val easing = easings[i?.easing] ?: fb.easing
            return AlmadarMotionIntent(durationMs = duration, easing = easing)
        }
        val motion = AlmadarMotionScale(
            durationsMs = durationsMs,
            easings = easings,
            enter = resolvedMotionIntent(motionAxis?.intents?.enter, fb.motion.enter),
            exit = resolvedMotionIntent(motionAxis?.intents?.exit, fb.motion.exit),
            hover = resolvedMotionIntent(motionAxis?.intents?.hover, fb.motion.hover),
            press = resolvedMotionIntent(motionAxis?.intents?.press, fb.motion.press),
            expand = resolvedMotionIntent(motionAxis?.intents?.expand, fb.motion.expand),
            transition = resolvedMotionIntent(motionAxis?.intents?.transition, fb.motion.transition),
            busyDelayMs = parseCssDurationMs(motionAxis?.busyDelay, fb.motion.busyDelayMs),
            awaitingSkeleton = motionAxis?.awaitingSkeleton ?: fb.motion.awaitingSkeleton,
        )

        val iconAxis = tokens.iconography
        val iconography = AlmadarIconographyScale(
            family = iconAxis?.family ?: fb.iconography.family,
            strokeWidth = parseCssNumber(iconAxis?.strokeWidth, fb.iconography.strokeWidth),
            defaultSize = parseCssLength(iconAxis?.defaultSize, fb.iconography.defaultSize),
        )

        val elevationAxis = tokens.elevation
        val elevation = AlmadarElevationScale(
            cardElevation = parseCssShadow(resolveShadowRef(elevationAxis?.cardElevation, tokens.shadows), fb.elevation.cardElevation),
            popoverElevation = parseCssShadow(resolveShadowRef(elevationAxis?.popoverElevation, tokens.shadows), fb.elevation.popoverElevation),
            dialogElevation = parseCssShadow(resolveShadowRef(elevationAxis?.dialogElevation, tokens.shadows), fb.elevation.dialogElevation),
            toastElevation = parseCssShadow(resolveShadowRef(elevationAxis?.toastElevation, tokens.shadows), fb.elevation.toastElevation),
            interactiveElevation = parseCssShadow(resolveShadowRef(elevationAxis?.interactiveElevation, tokens.shadows), fb.elevation.interactiveElevation),
            pressedElevation = parseCssShadow(resolveShadowRef(elevationAxis?.pressedElevation, tokens.shadows), fb.elevation.pressedElevation),
        )

        val geometryAxis = tokens.geometry
        val geometry = AlmadarGeometryScale(
            radiusContainer = parseCssLength(resolveRadiusRef(geometryAxis?.radiusContainer, tokens.radii), fb.geometry.radiusContainer),
            radiusInteractive = parseCssLength(resolveRadiusRef(geometryAxis?.radiusInteractive, tokens.radii), fb.geometry.radiusInteractive),
            radiusPill = parseCssLength(resolveRadiusRef(geometryAxis?.radiusPill, tokens.radii), fb.geometry.radiusPill),
            borderHairline = parseCssLength(resolveRadiusRef(geometryAxis?.borderHairline, tokens.radii), fb.geometry.borderHairline),
            borderStandard = parseCssLength(resolveRadiusRef(geometryAxis?.borderStandard, tokens.radii), fb.geometry.borderStandard),
            borderHeavy = parseCssLength(resolveRadiusRef(geometryAxis?.borderHeavy, tokens.radii), fb.geometry.borderHeavy),
            cornerShape = parseCssCornerShape(geometryAxis?.cornerShape, fb.geometry.cornerShape),
            cornerShapePill = parseCssCornerShape(geometryAxis?.cornerShapePill, fb.geometry.cornerShapePill),
            cornerShapeInteractive = parseCssCornerShape(geometryAxis?.cornerShapeInteractive, fb.geometry.cornerShapeInteractive),
            borderStyle = parseCssBorderStyle(geometryAxis?.borderStyle, fb.geometry.borderStyle),
            borderStyleInteractive = parseCssBorderStyle(geometryAxis?.borderStyleInteractive, fb.geometry.borderStyleInteractive),
        )

        val surfaceAxis = tokens.surface
        val surface = AlmadarSurfaceScale(
            backdrop = parseCssBackdrop(surfaceAxis?.backdrop, fb.surface.backdrop),
            cardImage = parseCssSurfaceImage(surfaceAxis?.cardImage, fb.surface.cardImage),
            pageImage = parseCssSurfaceImage(surfaceAxis?.pageImage, fb.surface.pageImage),
            pageImageSize = parseCssTileSizes(surfaceAxis?.pageImageSize, fb.surface.pageImageSize),
            diagram = parseCssColor(surfaceAxis?.diagram, fb.surface.diagram),
            edgeMask = parseCssSurfaceImage(surfaceAxis?.edgeMask, fb.surface.edgeMask),
            edgeHeight = parseCssResponsiveLength(surfaceAxis?.edgeHeight, fb.surface.edgeHeight),
            textureMask = parseCssSurfaceImage(surfaceAxis?.textureMask, fb.surface.textureMask),
            textureSize = parseCssTileSizes(surfaceAxis?.textureSize, fb.surface.textureSize),
            accentImage = parseCssSurfaceImage(surfaceAxis?.accentImage, fb.surface.accentImage),
            scrim = parseCssSurfaceImage(surfaceAxis?.scrim, fb.surface.scrim),
        )

        return AlmadarThemeValue(color, density, typeScale, motion, iconography, elevation, geometry, surface)
    }

    /** Zero-ish literal defaults used ONLY while resolving `fallback` itself
     *  (there is no earlier fallback to chain to). */
    private val bootstrapDefaults: AlmadarThemeValue by lazy {
        val zeroColor = Color.Black
        val zeroCurve = CssCurve(0f, 0f, 1f, 1f)
        val zeroEntry = AlmadarTypeEntry(16.sp, 20.sp)
        val zeroIntent = AlmadarTypeIntent(TextStyle(fontSize = 16.sp, lineHeight = 20.sp))
        val zeroShadow = CssShadow(zeroColor, 0.dp, 0.dp, 0.dp)
        val zeroMotionIntent = AlmadarMotionIntent(200, zeroCurve)
        AlmadarThemeValue(
            color = AlmadarColorPalette(primary = zeroColor, primaryHover = zeroColor, primaryForeground = zeroColor, secondary = zeroColor, secondaryHover = zeroColor, secondaryForeground = zeroColor, accent = zeroColor, accentForeground = zeroColor, muted = zeroColor, mutedForeground = zeroColor, background = zeroColor, foreground = zeroColor, card = zeroColor, cardForeground = zeroColor, surface = zeroColor, border = zeroColor, input = zeroColor, ring = zeroColor, error = zeroColor, errorForeground = zeroColor, success = zeroColor, successForeground = zeroColor, warning = zeroColor, warningForeground = zeroColor, info = zeroColor, infoForeground = zeroColor, tableHeader = zeroColor, tableBorder = zeroColor, tableRowHover = zeroColor, surfaceHover = zeroColor, borderHover = zeroColor, placeholder = zeroColor, scrim = zeroColor),
            density = AlmadarDensityScale(
                spacing = mapOf("space0" to 4.dp, "space1" to 4.dp, "space2" to 4.dp, "space3" to 4.dp, "space4" to 4.dp, "space5" to 4.dp, "space6" to 4.dp, "space7" to 4.dp, "space8" to 4.dp, "space9" to 4.dp, "space10" to 4.dp, "space11" to 4.dp, "space12" to 4.dp),
                buttonHeightSm = 40.dp, buttonHeightMd = 40.dp, buttonHeightLg = 40.dp, inputHeightSm = 40.dp, inputHeightMd = 40.dp, inputHeightLg = 40.dp, rowHeightCompact = 40.dp, rowHeightNormal = 40.dp, rowHeightSpacious = 40.dp, cardPaddingSm = 40.dp, cardPaddingMd = 40.dp, cardPaddingLg = 40.dp, dialogPadding = 40.dp, sectionGap = 40.dp
            ),
            typeScale = AlmadarTypeScale(
                displayFamily = null, bodyFamily = null, monoFamily = null,
                heading = AlmadarHeadingVoice(weight = FontWeight.Normal, transform = CssTextTransform.None, tracking = CssTracking(0.0, true), style = CssFontSlant.Normal, shadow = null),
                scale = mapOf("xs" to zeroEntry, "sm" to zeroEntry, "base" to zeroEntry, "lg" to zeroEntry, "xl" to zeroEntry, "2xl" to zeroEntry, "3xl" to zeroEntry, "4xl" to zeroEntry, "display-1" to zeroEntry, "display-2" to zeroEntry),
                headingMajor = zeroIntent, headingMinor = zeroIntent, bodyEmphasis = zeroIntent, bodyDefault = zeroIntent, bodyQuiet = zeroIntent, caption = zeroIntent, numeric = zeroIntent
            ),
            motion = AlmadarMotionScale(
                durationsMs = mapOf("instant" to 200, "fast" to 200, "normal" to 200, "slow" to 200, "dramatic" to 200),
                easings = mapOf("linear" to zeroCurve, "standard" to zeroCurve, "emphasized" to zeroCurve, "spring" to zeroCurve),
                enter = zeroMotionIntent, exit = zeroMotionIntent, hover = zeroMotionIntent, press = zeroMotionIntent, expand = zeroMotionIntent, transition = zeroMotionIntent,
                busyDelayMs = 300, awaitingSkeleton = false,
            ),
            iconography = AlmadarIconographyScale(family = "lucide", strokeWidth = 1.5, defaultSize = 16.dp),
            elevation = AlmadarElevationScale(cardElevation = zeroShadow, popoverElevation = zeroShadow, dialogElevation = zeroShadow, toastElevation = zeroShadow, interactiveElevation = zeroShadow, pressedElevation = zeroShadow),
            geometry = AlmadarGeometryScale(radiusContainer = 4.dp, radiusInteractive = 4.dp, radiusPill = 4.dp, borderHairline = 4.dp, borderStandard = 4.dp, borderHeavy = 4.dp, cornerShape = CssCornerShape.Round, cornerShapePill = CssCornerShape.Round, cornerShapeInteractive = CssCornerShape.Round, borderStyle = CssBorderStyle.Solid, borderStyleInteractive = CssBorderStyle.Solid),
            surface = AlmadarSurfaceScale(backdrop = null, cardImage = CssSurfaceImage.None, pageImage = CssSurfaceImage.None, pageImageSize = emptyList(), diagram = zeroColor, edgeMask = CssSurfaceImage.None, edgeHeight = CssResponsiveLength(0.dp, 0.0, 0.dp, 0.dp), textureMask = CssSurfaceImage.None, textureSize = emptyList(), accentImage = CssSurfaceImage.None, scrim = CssSurfaceImage.None)
        )
    }
}

enum class ColorMode { Light, Dark }

/** `dynamicColor` is deliberately NOT used — theme colors come from
 *  `AlmadarTheme`/tokens only, never the device wallpaper palette. */
@Composable
fun AlmadarTheme(tokens: ThemeTokensJson, mode: ColorMode, content: @Composable () -> Unit) {
    val resolved = AlmadarTheme.resolve(tokens, mode, AlmadarTheme.fallback)
    val colorScheme = if (mode == ColorMode.Dark) {
        darkColorScheme(primary = resolved.color.primary, secondary = resolved.color.secondary, background = resolved.color.background, surface = resolved.color.surface, error = resolved.color.error)
    } else {
        lightColorScheme(primary = resolved.color.primary, secondary = resolved.color.secondary, background = resolved.color.background, surface = resolved.color.surface, error = resolved.color.error)
    }
    val typography = Typography(bodyLarge = resolved.typeScale.bodyDefault.style, titleLarge = resolved.typeScale.headingMajor.style, titleMedium = resolved.typeScale.headingMinor.style, labelSmall = resolved.typeScale.caption.style)
    val shapes = Shapes(small = androidx.compose.foundation.shape.RoundedCornerShape(resolved.geometry.radiusInteractive), medium = androidx.compose.foundation.shape.RoundedCornerShape(resolved.geometry.radiusContainer), large = androidx.compose.foundation.shape.RoundedCornerShape(resolved.geometry.radiusPill))
    CompositionLocalProvider(
        LocalAlmadarTheme provides resolved,
        LocalAlmadarDensity provides resolved.density,
        LocalAlmadarMotion provides resolved.motion,
        LocalAlmadarIconography provides resolved.iconography,
        LocalAlmadarElevation provides resolved.elevation,
        LocalAlmadarGeometry provides resolved.geometry,
        LocalAlmadarSurface provides resolved.surface,
    ) {
        AlmadarBackdropHost { MaterialTheme(colorScheme = colorScheme, typography = typography, shapes = shapes, content = content) }
    }
}

val LocalAlmadarTheme = compositionLocalOf { AlmadarTheme.fallback }

/** The host's theme-mode control, the native twin of the web `useTheme()` context (`resolvedMode`,
 *  `toggleMode`). `toggle` asks the kernel for the opposite mode and re-resolves the theme. */
class AlmadarThemeModeControl(val isDark: Boolean, val toggle: () -> Unit)

val LocalAlmadarThemeMode = compositionLocalOf { AlmadarThemeModeControl(false) {} }

val LocalAlmadarDensity = compositionLocalOf { AlmadarTheme.fallback.density }
val LocalAlmadarMotion = compositionLocalOf { AlmadarTheme.fallback.motion }
val LocalAlmadarIconography = compositionLocalOf { AlmadarTheme.fallback.iconography }
val LocalAlmadarElevation = compositionLocalOf { AlmadarTheme.fallback.elevation }
val LocalAlmadarGeometry = compositionLocalOf { AlmadarTheme.fallback.geometry }
val LocalAlmadarSurface = compositionLocalOf { AlmadarTheme.fallback.surface }
